def is_mirror_word(word):
    # Define the mirror mapping for valid characters
    mirror_map = {
        'A': 'A', 'H': 'H', 'I': 'I', 'M': 'M', 'O': 'O', 'T': 'T', 'U': 'U', 'V': 'V', 'W': 'W', 'X': 'X', 'Y': 'Y'
    }

    # Reverse the word using slicing
    reversed_word = word[::-1]

    # Check if each character in the word has a corresponding mirrored character and matches the reversed word
    for i in range(len(word)):
        if word[i] not in mirror_map or mirror_map[word[i]] != reversed_word[i]:
            return 'NO'

    return 'YES'

